package kr.or.arte.seal.statistics.persistence;import kr.or.arte.seal.statistics.application.*;import org.springframework.stereotype.Repository;import java.time.LocalDate;import java.util.*;@Repository public class MyBatisStatisticsRepository implements StatisticsRepository {private final StatisticsMapper mapper;public MyBatisStatisticsRepository(StatisticsMapper m){mapper=m;}public StatisticsSnapshot query(UUID actor,LocalDate from,LocalDate to){var rows=mapper.query(actor,from,to);return new StatisticsSnapshot(group(rows,"REQUEST"),group(rows,"RESPONSE"),group(rows,"MAIL"),group(rows,"EVIDENCE"),group(rows,"RIGHTS"),group(rows,"RETENTION"));}private static List<StatusCount> group(List<MetricCount> rows,String category){return rows.stream().filter(r->category.equals(r.category())).map(r->new StatusCount(r.status(),r.count())).toList();}}
